std::pair<int,int> accepted(const std::vector<int>& readings) {
    int count = 0, sum = 0;
    for (int value : readings) {
        if (value == -999) break; // Sentinel is not data.
        if (value < 0) continue;
        sum += value;
        ++count;
        if (count == 3) break; // Bound accepted items, not attempts.
    }
    return {count, sum};
}

